import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"复合语句","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tutorials/Compound_Statement.md","filePath":"guide/tutorials/Compound_Statement.md"}`),a={name:`guide/tutorials/Compound_Statement.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="复合语句" tabindex="-1">复合语句 <a class="header-anchor" href="#复合语句" aria-label="Permalink to “复合语句”">​</a></h1><h2 id="前言与确认" tabindex="-1">前言与确认 <a class="header-anchor" href="#前言与确认" aria-label="Permalink to “前言与确认”">​</a></h2><p><code>SIF</code> 只能管一行，实在不够用。现实里的游戏充满“如果……就……”“重复 N 次”“一直做直到……”这样的逻辑，这就需要<strong>复合语句</strong>——能一次控制很多行的语句。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./../Quick_Start.html">快速开始</a>、<a href="./Statement.html">简单语句</a>和<a href="./Expression.html">表达式</a>。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><p>先确认一下我们现有的工程文件夹结构：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config</span></span>
<span class="line"><span> ├─ Emuera1824.exe</span></span>
<span class="line"><span> ├─ CSV/</span></span>
<span class="line"><span> └─ ERB/</span></span>
<span class="line"><span>     └─ System.erb</span></span></code></pre></div><p>其中，<code>System.erb</code>的代码为：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  Print</span><span style="color:#9CDCFE;"> Hello</span><span style="color:#9CDCFE;"> World</span><span style="color:#D4D4D4;">!</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><h2 id="if-根据条件选择分支" tabindex="-1">IF：根据条件选择分支 <a class="header-anchor" href="#if-根据条件选择分支" aria-label="Permalink to “IF：根据条件选择分支”">​</a></h2><p><code>IF</code> 会从多个分支里挑一个执行：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Age</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 18</span></span>
<span class="line"><span style="color:#C586C0;">  IF</span><span style="color:#9CDCFE;"> Age</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#B5CEA8;"> 6</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span><span style="color:#9CDCFE;"> 你是小朋友</span></span>
<span class="line"><span style="color:#C586C0;">  ELSEIF</span><span style="color:#9CDCFE;"> Age</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#B5CEA8;"> 18</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span><span style="color:#9CDCFE;"> 你是少年</span></span>
<span class="line"><span style="color:#C586C0;">  ELSE</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span><span style="color:#9CDCFE;"> 你是大人</span></span>
<span class="line"><span style="color:#C586C0;">  ENDIF</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><ul><li><code>IF 条件</code>：条件成立时，执行到下一个 <code>ELSEIF</code>/<code>ELSE</code>/<code>ENDIF</code> 为止；</li><li><code>ELSEIF 条件</code>：前面的条件都不成立时，再判断这个；</li><li><code>ELSE</code>：前面都不成立时执行；</li><li><code>ENDIF</code>：整个分支结束。</li></ul><p><strong>每一个 <code>IF</code> 都必须有对应的 <code>ENDIF</code></strong>，否则会报错：</p><div class="danger custom-block"><p class="custom-block-title">错误信息<a href="javascript:alert(&#39;TODO&#39;)">索引</a></p><blockquote><p>IFに対応するENDIFが設定されていない</p></blockquote><p>找不到与 IF 对应的 ENDIF。</p></div><h2 id="repeat-简单的重复" tabindex="-1">REPEAT：简单的重复 <a class="header-anchor" href="#repeat-简单的重复" aria-label="Permalink to “REPEAT：简单的重复”">​</a></h2><p><code>REPEAT</code> 到 <code>REND</code> 之间的内容会重复执行若干次。次数写在 <code>REPEAT</code> 后面：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#C586C0;">  REPEAT</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#569CD6;">    Print</span><span style="color:#9CDCFE;"> 第</span></span>
<span class="line"><span style="color:#569CD6;">    PrintV</span><span style="color:#9CDCFE;"> COUNT</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span><span style="color:#9CDCFE;"> 次循环</span></span>
<span class="line"><span style="color:#C586C0;">  REND</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>第0次循环</span></span>
<span class="line"><span>第1次循环</span></span>
<span class="line"><span>第2次循环</span></span></code></pre></div><p>注意计数的内置变量叫 <code>COUNT</code>，它是<strong>从 0 开始</strong>的。</p><h2 id="for-更灵活的循环" tabindex="-1">FOR：更灵活的循环 <a class="header-anchor" href="#for-更灵活的循环" aria-label="Permalink to “FOR：更灵活的循环”">​</a></h2><p><code>FOR</code> 也能循环，但可以自定义计数的变量、起点和终点：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#C586C0;">  FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">4</span></span>
<span class="line"><span style="color:#569CD6;">    PrintV</span><span style="color:#9CDCFE;"> I</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span></span>
<span class="line"><span style="color:#C586C0;">  NEXT</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span></code></pre></div><p><code>FOR I, 1, 4</code> 的意思是：让 <code>I</code> 从 <code>1</code> 开始，每轮加 1，直到 <code>I</code> 达到 <code>4</code> 之前停下来（所以不包含 4）。</p><h2 id="while-条件成立就一直做" tabindex="-1">WHILE：条件成立就一直做 <a class="header-anchor" href="#while-条件成立就一直做" aria-label="Permalink to “WHILE：条件成立就一直做”">​</a></h2><p><code>WHILE</code> 会在条件成立时不断重复，直到条件不再成立：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> I</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#C586C0;">  WHILE</span><span style="color:#9CDCFE;"> I</span><span style="color:#D4D4D4;"> &lt;</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#569CD6;">    PrintV</span><span style="color:#9CDCFE;"> I</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span></span>
<span class="line"><span style="color:#9CDCFE;">    I</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#C586C0;">  WEND</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>0</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span></code></pre></div><blockquote><p>如果循环里忘了让 <code>I</code> 变大，条件就永远成立，程序会陷入<strong>死循环</strong>。写到 <code>WHILE</code> 时，记得检查“这个条件最终会变假吗”。</p></blockquote><h2 id="break-与-continue" tabindex="-1">BREAK 与 CONTINUE <a class="header-anchor" href="#break-与-continue" aria-label="Permalink to “BREAK 与 CONTINUE”">​</a></h2><p>在循环里，我们还能用两个小开关：</p><ul><li><code>BREAK</code>：立刻跳出整个循环；</li><li><code>CONTINUE</code>：跳过本轮剩下的内容，直接进入下一轮。</li></ul><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#C586C0;">  FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">10</span></span>
<span class="line"><span style="color:#C586C0;">    SIF</span><span style="color:#9CDCFE;"> I</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#C586C0;">      CONTINUE</span><span style="color:#6A9955;">   ; 3 不打印，直接下一轮</span></span>
<span class="line"><span style="color:#C586C0;">    SIF</span><span style="color:#9CDCFE;"> I</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 6</span></span>
<span class="line"><span style="color:#C586C0;">      BREAK</span><span style="color:#6A9955;">      ; 到 6 就整个结束</span></span>
<span class="line"><span style="color:#569CD6;">    PrintV</span><span style="color:#9CDCFE;"> I</span></span>
<span class="line"><span style="color:#569CD6;">    PrintL</span></span>
<span class="line"><span style="color:#C586C0;">  NEXT</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>5</span></span></code></pre></div><h2 id="selectcase-多路分支" tabindex="-1">SELECTCASE：多路分支 <a class="header-anchor" href="#selectcase-多路分支" aria-label="Permalink to “SELECTCASE：多路分支”">​</a></h2><p>当一个值有很多种可能时，<code>IF</code> 会写得很啰嗦，这时用 <code>SELECTCASE</code> 更清爽：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Command</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#C586C0;">  SELECTCASE</span><span style="color:#9CDCFE;"> Command</span></span>
<span class="line"><span style="color:#C586C0;">    CASE</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 执行第一项</span></span>
<span class="line"><span style="color:#C586C0;">    CASE</span><span style="color:#B5CEA8;"> 2</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">3</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 执行第二或第三项</span></span>
<span class="line"><span style="color:#C586C0;">    CASE</span><span style="color:#B5CEA8;"> 10</span><span style="color:#569CD6;"> TO</span><span style="color:#B5CEA8;"> 20</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 执行第</span><span style="color:#B5CEA8;"> 10</span><span style="color:#9CDCFE;"> 到</span><span style="color:#B5CEA8;"> 20</span><span style="color:#9CDCFE;"> 项</span></span>
<span class="line"><span style="color:#C586C0;">    CASEELSE</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 其他情况</span></span>
<span class="line"><span style="color:#C586C0;">  ENDSELECT</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p><code>CASE</code> 支持多种写法：单个值（<code>CASE 1</code>）、多个值（<code>CASE 2, 3</code>）、范围（<code>CASE 10 TO 20</code>）。都不匹配时执行 <code>CASEELSE</code>。</p><h2 id="嵌套" tabindex="-1">嵌套 <a class="header-anchor" href="#嵌套" aria-label="Permalink to “嵌套”">​</a></h2><p>复合语句可以互相嵌套，比如在循环里写判断：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#C586C0;">  FOR</span><span style="color:#9CDCFE;"> I</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">6</span></span>
<span class="line"><span style="color:#C586C0;">    IF</span><span style="color:#9CDCFE;"> I</span><span style="color:#D4D4D4;"> %</span><span style="color:#B5CEA8;"> 2</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 偶数</span></span>
<span class="line"><span style="color:#C586C0;">    ELSE</span></span>
<span class="line"><span style="color:#569CD6;">      PrintL</span><span style="color:#9CDCFE;"> 奇数</span></span>
<span class="line"><span style="color:#C586C0;">    ENDIF</span></span>
<span class="line"><span style="color:#C586C0;">  NEXT</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>只要记住<strong>每一层都要完整地闭合</strong>（<code>IF</code>…<code>ENDIF</code>、<code>REPEAT</code>…<code>REND</code>），缩进对齐，就不容易出错。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li><code>IF/ELSEIF/ELSE/ENDIF</code> 做条件分支；</li><li><code>REPEAT/REND</code>、<code>FOR/NEXT</code>、<code>WHILE/WEND</code> 做循环；</li><li><code>BREAK</code> 跳出循环，<code>CONTINUE</code> 进入下一轮；</li><li><code>SELECTCASE/CASE/CASEELSE/ENDSELECT</code> 做多路分支；</li><li>复合语句可以嵌套，但每层都要闭合。</li></ul><p>下一步，我们学习如何把一段逻辑打包成可以重复使用的<strong>函数</strong>：<a href="./Function.html">函数的定义与用法</a>。</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};